customer_analysis.report_turtle:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <urn:retail:row:check2> ;
            sh:resultMessage "Less than 1 values on <urn:retail:row:check2>-><urn:retail:field:CustomerID>" ;
            sh:resultPath <urn:retail:field:CustomerID> ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:minCount 1 ;
                    sh:path <urn:retail:field:CustomerID> ] ] .

quantity_sign.report_turtle:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .

nonnegative_price.report_turtle:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <urn:retail:row:check2> ;
            sh:resultMessage "Value is not >= Literal(\"0\", datatype=xsd:integer)" ;
            sh:resultPath <urn:retail:field:UnitPrice> ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinInclusiveConstraintComponent ;
            sh:sourceShape [ sh:minCount 1 ;
                    sh:minInclusive 0 ;
                    sh:path <urn:retail:field:UnitPrice> ] ;
            sh:value -1.0 ] .

